/* The House: a guttural, crushed intercom character inspired by horror table games.
   A single neural voice, lowered and ring-modulated; no operating-system speech. */
function shapeHouseVoice(input,sampleRate=44100){const pitch=.65,n=Math.ceil(input.length/pitch),out=new Float32Array(n);const low=1-Math.exp(-2*Math.PI*2650/sampleRate),chest=1-Math.exp(-2*Math.PI*190/sampleRate),high=Math.exp(-2*Math.PI*55/sampleRate);let lp=0,body=0,hp=0,previous=0,peak=0,held=0;const shadow=Math.round(sampleRate*.026),dry=new Float32Array(n);for(let i=0;i<n;i++){const at=i*pitch,k=Math.floor(at),f=at-k,x=(input[k]||0)*(1-f)+(input[k+1]||0)*f;hp=high*(hp+x-previous);previous=x;lp+=low*(hp-lp);body+=chest*(lp-body);const warm=lp+body*.32;const growl=warm*(.76+.24*Math.cos(2*Math.PI*67*i/sampleRate));const crushed=Math.tanh(growl*3.4)/2.2;if(i%3===0)held=Math.round(crushed*512)/512;dry[i]=crushed*.86+held*.14;const value=dry[i]+(dry[i-shadow]||0)*.16;out[i]=value;peak=Math.max(peak,Math.abs(value))}const gain=peak>.001?Math.min(1.65,.72/peak):1,fade=Math.min(400,n/2);for(let i=0;i<n;i++)out[i]*=gain*Math.min(1,i/fade,(n-1-i)/fade);return out}
